            "status": "pass" if (thickness_ok and r3_ok) else "fail",
            "value": [round(empty_vol, 3), round(walled_vol, 3)],
            "method": f"bore probe at (0,y,30) with D={bore_diam}, core_ratio={empty_vol}, wall_ratio={walled_vol}",
            "criteria": [
                {"condition": "Face plate thickness >= 4mm", "measured": y_max - y_min, "ok": thickness_ok},
                {"condition": "Central bore diameter 22.5mm", "measured": empty_vol, "ok": r3_ok}
            ],
            "note": f"Empty: {empty_vol}, Walled: {walled_vol}"
        }
    except Exception as e:
        results["R2_R3"] = {"status": "error", "value": None, "method": "bore probe", "criteria": [], "note": str(e)}

